cpp.solutions:
## solutions



#### depth first

```cpp
int treeSum(Node* root) {
  if (root == nullptr) {
    return 0;
  }
  return root->val + treeSum(root->left) + treeSum(root->right);
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)



#### breadth first

```cpp
#include <queue>

int treeSum(Node* root) {
  std::queue<Node*> queue;

  if (root != nullptr) {
    queue.push(root);
  }

  int sum = 0;
  while (queue.size() > 0) {
    Node* current = queue.front();
    queue.pop();
    sum += current->val;
    if (current->left) {
      queue.push(current->left);
    }
    if (current->right) {
      queue.push(current->right);
    }
  }

  return sum;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)
